def is_palindrome(text):
    temp_chars = []
    for i in range(len(text)):
        char = text[i]
        if 'a' <= char.lower() <= 'z' or '0' <= char <= '9':
            temp_chars.append(char.lower())

    char_dict = {i: temp_chars[i] for i in range(len(temp_chars))}

    for i in range(len(char_dict) // 2):
        if char_dict[i] != char_dict[len(char_dict) - 1 - i]:
            return False

    return True

