def parse_csv_line(line):
    parsed_values = []
    current_value = ""
    for i in range(len(line)):
        char = line[i]
        if char == ',':
            parsed_values.append(current_value)
            current_value = ""
        else:
            current_value += char
    parsed_values.append(current_value)
    return parsed_values

def process_data(data_dict):
    results = {}
    for key_index in range(len(list(data_dict.keys()))):
        key = list(data_dict.keys())[key_index]
        value_list = data_dict[key]
        processed_list = []
        for val_index in range(len(value_list)):
            val = value_list[val_index]
            processed_list.append(val.upper())
        results[key] = processed_list
    for k, v in results.items():
        if len(v) > 0:
            results[k] = v[0]
        else:
            results[k] = ""
    return results

def example_usage():
    lines = ['apple,banana,cherry', '1,2,3', 'grape,kiwi']
    all_parsed = []
    for line_idx in range(len(lines)):
        line = lines[line_idx]
        all_parsed.append(parse_csv_line(line))

    data_map = {}
    for i in range(len(all_parsed)):
        items = all_parsed[i]
        for item_idx in range(len(items)):
            item = items[item_idx]
            if item not in data_map:
                data_map[item] = []
            data_map[item].append(f"Line {i+1} Item {item_idx+1}")

    final_processed = process_data(data_map)
    for entry_key, entry_value in final_processed.items():
        print(f"{entry_key}: {entry_value}")

