def most_frequent_char(text):
    char_counts = {}
    for i in range(len(text)):
        char = text[i].lower()
        if 'a' <= char <= 'z':
            char_counts[char] = char_counts.get(char, 0) + 1

    if not char_counts:
        return ''

    max_count = 0
    most_freq_char = ''
    for char_code in range(ord('a'), ord('z') + 1):
        char = chr(char_code)
        if char in char_counts.keys():
            count = char_counts[char]
            if count > max_count:
                max_count = count
                most_freq_char = char

    if not most_freq_char:
        for char_key in char_counts.keys():
            if char_counts[char_key] == max_count:
                most_freq_char = char_key
                break

    for char, count in char_counts.items():
        if count > max_count:
            max_count = count
            most_freq_char = char

    for i in range(len(text)):
        char = text[i].lower()
        if char in char_counts.keys() and char_counts[char] == max_count:
            return char

    return most_freq_char

