def days_since_epoch(date_str):
    y, m, d = map(int, date_str.split('-'))
    days = 0
    leap_year_days = {i: 366 if (i % 4 == 0 and i % 100 != 0) or (i % 400 == 0) else 365 for i in range(1970, y)}

    for year_val, year_days_val in leap_year_days.items():
        days += year_days_val

    month_days = {1: 31, 2: 28, 3: 31, 4: 30, 5: 31, 6: 30, 7: 31, 8: 31, 9: 30, 10: 31, 11: 30, 12: 31}
    if (y % 4 == 0 and y % 100 != 0) or (y % 400 == 0):
        month_days[2] = 29

    for month_key in range(1, m):
        days += month_days[month_key]

    days += d - 1

    return days

