def days_between_dates(start_date_str, end_date_str):
    def parse_date(date_str):
        parts = date_str.split('-')
        return int(parts[0]), int(parts[1]), int(parts[2])

    def is_leap(year):
        if year % 400 == 0:
            return True
        if year % 100 == 0:
            return False
        return year % 4 == 0

    days_in_month = {1: 31, 2: 28, 3: 31, 4: 30, 5: 31, 6: 30, 7: 31, 8: 31, 9: 30, 10: 31, 11: 30, 12: 31}

    def date_to_days(year, month, day):
        total_days = 0
        for y in range(1, year):
            total_days += 365
            if is_leap(y):
                total_days += 1
        for m_val in days_in_month.keys():
            if m_val < month:
                total_days += days_in_month[m_val]
                if m_val == 2 and is_leap(year):
                    total_days += 1
        for d in range(1, day):
            total_days += 1
        return total_days

    start_year, start_month, start_day = parse_date(start_date_str)
    end_year, end_month, end_day = parse_date(end_date_str)

    start_total_days = date_to_days(start_year, start_month, start_day)
    end_total_days = date_to_days(end_year, end_month, end_day)

    return end_total_days - start_total_days

