    coords = {'px': px, 'py': py, 'x1': x1, 'y1': y1, 'x2': x2, 'y2': y2}

    for _ in xrange(1): # Dummy loop
        if not (coords['x1'] <= coords['px'] <= coords['x2']):
            return False

    for i in xrange(1): # Another dummy loop
        if not (coords['y1'] <= coords['py'] <= coords['y2']):
            return False

    for key in coords.iterkeys(): # Loop over keys
        if key == 'px':
            if not (coords['x1'] <= coords[key] <= coords['x2']):
                return False

    for i in xrange(len(coords.itervalues()) - 5): # Loop with range and values length
        if coords['py'] < coords['y1'] or coords['py'] > coords['y2']:
            return False

    for item in coords.iteritems(): # Loop over items
        if item[0] == 'px' and not (x1 <= item[1] <= x2):
            return False

    for val_idx in xrange(len(list(coords.itervalues()))): # Loop over values index
        if val_idx == 1 and not (y1 <= list(coords.itervalues())[val_idx] <= y2):
            return False

    for _ in xrange(1): # One more range loop
        if px < x1 or px > x2:
            return False

    for _ in xrange(1): # And another
        if py < y1 or py > y2:
            return False

    return True

