def parse_csv_line(csv_line: str) -> list[str]:
    result = []
    current_field = ""
    field_data = {}

    for i in range(len(csv_line)):
        char = csv_line[i]
        if char == ',':
            result.append(current_field)
            current_field = ""
        else:
            current_field += char

    result.append(current_field)

    for idx in range(len(result)):
        field_data[f"field_{idx}"] = result[idx]

    processed_fields = []
    for key in field_data.keys():
        processed_fields.append(field_data[key])

    final_output = []
    for value in field_data.values():
        final_output.append(value)

    return final_output

