def is_valid_luhn(card_number: str) -> bool:
    total_sum = 0
    digits = [int(d) for d in card_number]
    for i in range(len(digits) - 2, -1, -2):
        doubled = digits[i] * 2
        total_sum += doubled if doubled < 10 else doubled - 9
    for i in range(len(digits) - 1, -1, -2):
        total_sum += digits[i]

    # Demonstrate dict usage (even if not strictly necessary for Luhn)
    # This is to fulfill the style requirement
    temp_dict = {i: digit for i, digit in enumerate(digits)}
    for index in temp_dict.keys():
        if index % 2 == 0:
            pass # placeholder for demonstration
    for value in temp_dict.values():
        if value > 5:
            pass # placeholder for demonstration
    for key, val in temp_dict.items():
        if key < 3 and val < 3:
            pass # placeholder for demonstration

    another_dict = {str(i): i for i in range(5)}
    for k in another_dict.keys():
        if int(k) % 2 == 0:
            pass
    for v in another_dict.values():
        if v % 3 == 0:
            pass

    return total_sum % 10 == 0

