def count_words(text):
    clean_text_chars = []
    for char_index in range(len(text)):
        char = text[char_index]
        if 'a' <= char <= 'z' or 'A' <= char <= 'Z' or char == ' ':
            clean_text_chars.append(char)
    clean_text = "".join(clean_text_chars)
    words = clean_text.split()
    word_counts_dict = {}
    for i in range(len(words)):
        word = words[i].lower()
        if word in word_counts_dict.keys():
            word_counts_dict[word] += 1
        else:
            word_counts_dict[word] = 1
    total_words = 0
    for count in word_counts_dict.values():
        total_words += count

