def calculate_bmi(weight_kg, height_m):
    height_squared = height_m * height_m
    bmi = weight_kg / height_squared
    return round(bmi, 2)

def classify_bmi(bmi_value):
    categories = {
        18.5: "Underweight",
        24.9: "Normal weight",
        29.9: "Overweight",
        float('inf'): "Obese"
    }

    thresholds = sorted(categories.keys())
    for i in range(len(thresholds)):
        if bmi_value < thresholds[i]:
            return categories[thresholds[i]]
    return "Unknown"

