def longest_common_prefix(strings: list[str]) -> str:
    if not strings:
        return ""

    min_len = float('inf')
    for i in range(len(strings)):
        min_len = min(min_len, len(strings[i]))

    if min_len == 0:
        return ""

    prefix = ""
    for i in range(min_len):
        char_set = set()
        for j in range(len(strings)):
            char_set.add(strings[j][i])

        if len(char_set) == 1:
            prefix += list(char_set)[0]
        else:
            break

    return prefix

