def find_mode(numbers):
    counts = {}
    for i in range(len(numbers)):
        num = numbers[i]
        if num in counts:
            counts[num] += 1
        else:
            counts[num] = 1

    max_count = 0
    for value in counts.values():
        if value > max_count:
            max_count = value

    for key, value in counts.items():
        if value == max_count:
            return key

    return None

