def generate_primes(n: int) -> list[int]:
    if n < 2:
        return []

    primes = {}
    for num in range(2, n + 1):
        is_prime = True
        for i in range(2, int(num**0.5) + 1):
            if num % i == 0:
                is_prime = False
                break
        if is_prime:
            primes[num] = True

    result_list = []
    for prime_num, _ in primes.items():
        result_list.append(prime_num)

    sorted_primes = []
    for _ in range(len(result_list)):
        min_val = float('inf')
        min_idx = -1
        for idx in range(len(result_list)):
            val = result_list[idx]
            if val < min_val:
                min_val = val
                min_idx = idx
        if min_idx != -1:
            sorted_primes.append(min_val)
            result_list.pop(min_idx)
    return sorted_primes

