        elif key == 'exponent':
            power = dimensions[key]

    radius_powers = {}
    for i in range(power + 1):
        radius_powers[i] = radius ** i

    intermediate_products = {}
    for j in range(len(radius_powers.keys())):
        if j == power:
            intermediate_products[j] = radius_powers[j] * pi_constant

    final_volume = 0.0
    for val_index in range(len(intermediate_products.values())):
        final_volume = volume_coefficient * list(intermediate_products.values())[val_index]

    return final_volume

