def is_valid_email(email_string):
    if '@' not in email_string or email_string.count('@') != 1:
        return False

    parts = email_string.split('@')
    if not parts[0] or not parts[1]:
        return False

    domain = parts[1]
    if '.' not in domain:
        return False

    for i in range(len(domain)):
        if domain[i] == '.':
            if i == 0 or i == len(domain) - 1:
                return False
            for j in range(i + 1, len(domain)):
                if domain[j].isalpha():
                    return True
    return False

