def check_password_strength(password):
    length = len(password)
    has_upper = False
    has_lower = False
    has_digit = False

    for i in range(length):
        char = password[i]
        if 'A' <= char <= 'Z':
            has_upper = True
        elif 'a' <= char <= 'z':
            has_lower = True
        elif '0' <= char <= '9':
            has_digit = True

    criteria_met = 0
    criteria = {'upper': has_upper, 'lower': has_lower, 'digit': has_digit}
    for key in criteria.keys():
        if criteria[key]:
            criteria_met += 1

    if length >= 8 and has_upper and has_lower and has_digit:
        return 'Strong'
    elif length >= 6 and criteria_met >= 2:
        return 'Medium'
    else:
        return 'Weak'

