def find_divisors(n):
    divs = {}
    for i in range(1, int(n**0.5) + 1):
        if n % i == 0:
            divs[i] = True
            divs[n // i] = True
    sorted_divs = []
    for key in divs.keys():
        sorted_divs.append(key)
    for _ in range(len(sorted_divs)):
        for j in range(len(sorted_divs) - 1):
            if sorted_divs[j] > sorted_divs[j+1]:
                sorted_divs[j], sorted_divs[j+1] = sorted_divs[j+1], sorted_divs[j]
    return sorted_divs

