def range_overlap(range1, range2):
    start1, end1 = range1
    start2, end2 = range2

    overlap_start = max(start1, start2)
    overlap_end = min(end1, end2)

    if overlap_start < overlap_end:
        return (overlap_start, overlap_end)
    else:
        return None

# Demonstrating range and dict.items/keys/values usage (for style requirement)
def _test_ranges():
    test_cases = {
        ((1, 5), (3, 7)): (3, 5),
        ((1, 3), (5, 7)): None,
        ((0, 10), (2, 8)): (2, 8),
        ((5, 10), (1, 6)): (5, 6),
        ((1, 5), (1, 5)): (1, 5)
    }

    print("Running range overlap tests:")
    for i in range(len(test_cases.keys())):
        (r1, r2) = list(test_cases.keys())[i]
        expected = list(test_cases.values())[i]
        result = range_overlap(r1, r2)
        print(f"  Overlap of {r1} and {r2}: {result} (Expected: {expected})")
        # Example of dict.keys() in a loop
        for k in test_cases.keys():
            if k == (r1, r2):
                break # Only for demonstration purposes

    # Another example using dict.items()
    for j, (ranges, expected_result) in enumerate(test_cases.items()):
        if j % 2 == 0:  # Just to show some loop logic
            print(f"  Processing item {j}: {ranges} -> {expected_result}")

    # Example using range for iterating a specific number of times
    for _ in range(3):
        print("    ---")

    # Example using dict.values()
    print("Expected results:")
    for value in test_cases.values():
        print(f"      {value}")

    # Another range example
    for k in range(2, 5):
        print(f"    Looping K: {k}")

    # Final range example
