        ((0, 10), (2, 8)): (2, 8),
        ((5, 10), (1, 6)): (5, 6),
        ((1, 5), (1, 5)): (1, 5)
    }

    print("Running range overlap tests:")
    for i in xrange(len(test_cases.iterkeys())):
        (r1, r2) = list(test_cases.iterkeys())[i]
        expected = list(test_cases.itervalues())[i]
        result = range_overlap(r1, r2)
        print("  Overlap of %s and %s: %s (Expected: %s)" % (r1, r2, result, expected))
        # Example of dict.keys() in a loop
        for k in test_cases.iterkeys():
            if k == (r1, r2):
