    if not words:
        return ""

    current_line = []
    lines = []
    current_length = 0

    for i in range(len(words)):
        word = words[i]
        if current_length == 0:
            current_line.append(word)
            current_length = len(word)
        elif current_length + 1 + len(word) <= max_width:
