    domain_part = parts[1] if len(parts) > 1 else parts[0]

    if domain_part.startswith('www.'):
        domain_part = domain_part[4:]

    dot_index = domain_part.find('/')
    if dot_index != -1:
        domain_part = domain_part[:dot_index]

    segments = domain_part.split('.')

    tld_length = len(segments[-1]) 

    for i in xrange(len(segments) - 1, -1, -1):
        if len(segments[i]) > 0:
            tld_length = len(segments[i])
