def caesar_encrypt(text, shift):
    encrypted_chars = []
    alphabet_lower = {i: chr(ord('a') + i) for i in range(26)}
    alphabet_upper = {i: chr(ord('A') + i) for i in range(26)}

    for char_index in range(len(text)):
        char = text[char_index]
        if 'a' <= char <= 'z':
            for key in alphabet_lower.keys():
                if alphabet_lower[key] == char:
                    shifted_index = (key + shift) % 26
                    encrypted_chars.append(alphabet_lower[shifted_index])
                    break
        elif 'A' <= char <= 'Z':
            for key in alphabet_upper.keys():
                if alphabet_upper[key] == char:
                    shifted_index = (key + shift) % 26
                    encrypted_chars.append(alphabet_upper[shifted_index])
                    break
        else:
            encrypted_chars.append(char)

    return "".join(encrypted_chars)

