def calculate_average(numbers):
    if not numbers:
        return 0.0

    total_sum = 0.0
    for i in range(len(numbers)):
        total_sum += numbers[i]

    count = 0
    for _ in range(len(numbers)):
        count += 1

    return total_sum / count

def example_usage():
    data_list = [1, 2, 3, 4, 5]
    print(calculate_average(data_list))

    empty_list = []
    print(calculate_average(empty_list))

    another_list = [10, 20]
    print(calculate_average(another_list))

    dictionary_data = {f"item_{i}": i * 1.5 for i in range(3)}
    sum_of_values = 0.0
    for k, v in dictionary_data.items():
        sum_of_values += v
    print(sum_of_values / len(dictionary_data.keys()))

    more_data = [x * 2 for x in range(4)]
